"""O'Reilly Auto Parts category inventory from the live storefront taxonomy.

Source of truth: the server-rendered ``window._ost.childCategories`` array that
O'Reilly emits on every category page. The Shop All hub
(https://www.oreillyauto.com/shop/b) lists the departments; each department page
lists the product-bearing children that this inventory schedules.

Captured 2026-10-18 through the repository's configured ScrapeOps **US
residential** route (the datacenter route answers with a challenge envelope):
**34 departments** and **1,321 child categories**. A department landing page
is a navigation hub with no product bootstrap (no ``totalResults``), so the DAG
schedules the children -- each child is a real PLP (``brakes/brake-drums---rotors``
reported 8,749 results / 648 products on capture).

Grouped ``{department: {leaf: {url, category_path, subcategory, department}}}``
mapping as required by the base listing spider contract. ``leaf`` is the site's
own trailing slug. The 30 leaves whose slug repeats in another department, or
matches a department key (e.g. ``performance-brakes``), keep a department prefix
so every leaf is globally unique for the per-category GCS output path.
``subcategory`` keeps the site's original child slug and ``category_path`` the
display name the spider writes into every item.
"""

