def child_categories(text: str) -> list[dict[str, str]]:
    """Decode the authoritative ``window._ost.childCategories`` assignment.

    Every entry carries a nested ``thumbnailUri`` object, so the array is bracket
    matched and read as a Python literal rather than matched one object at a time.
    """
    marker = re.search(r"window\._ost\.childCategories\s*=\s*\[", text)
    if not marker:
        return []
    start = marker.end() - 1
    depth = 0
    end = None
    for index in range(start, len(text)):
        if text[index] == "[":
            depth += 1
        elif text[index] == "]":
            depth -= 1
            if depth == 0:
                end = index
                break
    if end is None:
        return []
    source = text[start:end + 1]
    for literal, replacement in (
        (r"\btrue\b", "True"),
        (r"\bfalse\b", "False"),
        (r"\bnull\b", "None"),
    ):
        source = re.sub(literal, replacement, source)
    out = []
    for entry in ast.literal_eval(source):
        name = entry.get("hierarchyDescription") or entry.get("name")
        url = entry.get("url")
        if name and url:
            out.append({"name": unescape(name), "url": urljoin(BASE_URL, url)})
    return sorted(out, key=lambda item: (item["name"].lower(), item["url"]))
